def group(r):
 p=r['question'][':question/problem'];f=r['question'][':question/answer-fields'][0];v=[a[':answer/value'] for a in f[':answer-field/choices']];return ('display' if '$$' in p else 'inline')+'/'+('blank' if len(v)==1 else 'absence-bank' if 'No such entry' in v else 'numeric-bank')
